/*
 * `satisfies` without `as const`, deliberately. The shape is still checked and
 * `keyof typeof` is still the literal union of the 115 names, but each path
 * string stays `string` instead of becoming its own literal type. Across a
 * 100KB table of very long strings that difference is most of the file's
 * type-checking cost, and nothing needs to know that `Home`'s body is that
 * exact string.
 *
 * It also has to stay on the same line as the closing brace: `const x = {…}` is
 * a complete statement, so a newline before `satisfies` ends it and the rest
 * parses as garbage.
 */

/** The literal union of every available glyph name. A typo is a compile error. */
export type IconName = keyof typeof icons;

export default icons;
